import{_ as i,l as n,o as e,c as s,v as r,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"列压缩：字典、RLE、位打包","description":"","frontmatter":{"title":"列压缩：字典、RLE、位打包","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/column-compression.md","filePath":"cs/column-compression.md","lastUpdated":1789023840000}'),m={name:"cs/column-compression.md"};function E(h,a,u,_,A,B){const t=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="列压缩-字典、rle、位打包" tabindex="-1">列压缩：字典、RLE、位打包 <a class="header-anchor" href="#列压缩-字典、rle、位打包" aria-label="Permalink to &quot;列压缩：字典、RLE、位打包&quot;">​</a></h1><div class="epigraph"><p>列上值域窄、重复多，编码比通用压缩更懂查询：比较可以在编码空间做，不必先还原成行。</p><footer>—— 据 Abadi, Madden and Ferreira 列存压缩；Zukowski 等；C-Store</footer></div><p><a href="/cs/columnar-pax">上一课</a>把列放在页或文件里。本课不重画 PAX。缺口是块内编码：分析列常低 NDV、排序后连续重复。字典、游程（RLE）、位打包（bit-packing）让扫描更少字节，且谓词有时能直接打在编码上（late decompression）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用 gzip 把块变成需先解压再查的黑盒，谓词无法下推进压缩域。数据库编码要：<strong>可跳过、可过滤、最好可比较</strong>。字典：值→整数码，码上建比较或位图。RLE：有序列上 <code>(值, 长度)</code>。位打包：码宽按 max 码动态选 \\(b\\) 位，不对齐浪费。缺口是按列统计选编码，不是「打开压缩开关」。</p><p>NULL 用位图，不进字典。增量编码、frame-of-reference 服务有序整数。本课钉三类主干。</p><p><span class="marginnote">Abadi, Madden, Ferreira，VLDB 2006 一类工作讨论压缩与查询。C-Store 把编码当一等设计。轻量编码通常胜过分块 gzip 在 CPU 上，除非网络传输瓶颈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ANALYZE 看 NDV、有序度、平均游程。选编码 → 写入列块头。扫描：向量化解码到列向量，或对字典码做谓词再回表值。连接：字典码若全局字典才可当键，局部字典要先解码或统一映射。</p><p>与 LSM：SST 内列块各有编码，compaction 重编码。与向量化：解码循环是 CPU 热点，编译执行可生成特化解码器。</p>',10)),(e(),l(c,null,{default:o(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E5%88%97%E5%9D%97%22%5D%20--%3E%20DICT%5B%22%E5%AD%97%E5%85%B8%E7%A0%81%22%5D%0A%20%20COL%20--%3E%20RLE%5B%22%E6%B8%B8%E7%A8%8B%22%5D%0A%20%20COL%20--%3E%20BP%5B%22%E4%BD%8D%E6%89%93%E5%8C%85%22%5D%0A%20%20DICT%20--%3E%20PRED%5B%22%E7%A0%81%E4%B8%8A%E8%B0%93%E8%AF%8D%22%5D%0A%20%20RLE%20--%3E%20SKIP%5B%22%E6%8C%89%E6%B8%B8%E7%A8%8B%E8%B7%B3%E8%BF%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>压缩改变代价模型：页数下降，CPU 上升。校准必须用压缩后扫描微基准，否则优化器以为磁盘是瓶颈。延迟物化：先对编码列过滤，再解码投影列。</p><p>更新：编码块不可原地改一行，常写新块——列存更新代价的一部分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Parquet 页头里的具体编码枚举——下一课格式标准。也不把 LZ4 当字典的替代定义。zone map 用 min/max 跳过，可在压缩块前。</p><p>后课默认：分析列块带编码；谓词尽量在码空间。Parquet/ORC：把编码、统计、row group 收成可交换文件。</p><p>编码是查询友好的压缩，不是备份压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>字典、RLE、位打包服务扫描与过滤，常可延迟解码。</li><li>编码选择看 NDV 与有序度；代价模型要重校准。</li><li>Parquet / ORC 下一课：开放列存文件合同。</li><li>出处：Abadi, Madden, Ferreira；C-Store；Zukowski 等。</li></ul>',9))])}const D=i(m,[["render",E]]);export{C as __pageData,D as default};
